	cmd := exec.CommandContext(promptCtx, g.Binary(), args...)
	cmd.Dir = dir
	cmd.Stdin = nil
	cmd.Env = append(filterEnv(os.Environ(), "ENTIRE_TEST_TTY"), "ACCESSIBLE=1")
	setupProcessGroup(cmd)
	cmd.WaitDelay = 5 * time.Second

