	if loaded.TokenUsage.OutputTokens != state.TokenUsage.OutputTokens {
		t.Errorf("TokenUsage.OutputTokens = %d, want %d", loaded.TokenUsage.OutputTokens, state.TokenUsage.OutputTokens)
