	if err := repo.Storer.SetReference(ref); err != nil {
		t.Fatalf("failed to create shadow branch: %v", err)
	}

	// Verify branch exists
	_, err = repo.Reference(refName, true)
	if err != nil {
		t.Fatalf("shadow branch should exist: %v", err)
