package agents

import (
	"regexp"
	"testing"
)

func TestCursorCLI_ReadinessMatcherPattern(t *testing.T) {
	t.Parallel()

	pattern := (&CursorCLI{}).startupPromptPattern()

	if matched := regexp.MustCompile(pattern).MatchString("Plan, search, build anything"); !matched {
		t.Fatalf("startup pattern %q did not match current Cursor startup text", pattern)
	}

	if matched := regexp.MustCompile(pattern).MatchString("/ commands"); !matched {
		t.Fatalf("startup pattern %q did not match legacy Cursor startup text", pattern)
	}
}

func TestGemini_ReadinessMatcherPattern(t *testing.T) {
	t.Parallel()

	pattern := (&Gemini{}).startupDialogPattern()

	if matched := regexp.MustCompile(pattern).MatchString("New Agents Discovered"); !matched {
		t.Fatalf("startup dialog pattern %q did not match Gemini discovery dialog", pattern)
	}

	if matched := regexp.MustCompile(pattern).MatchString("Type your message"); !matched {
		t.Fatalf("startup dialog pattern %q did not match Gemini prompt", pattern)
	}
}

